#include <cstring>
#include <vector>
#define main hecbench_original_main
#include "dp4a-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
template<class T>void study_type(int n,int repeat,std::vector<double>&times,std::vector<double>&values,std::vector<double>&expected,bool warmup){std::vector<T>host(n),out(n/4096);for(int i=0;i<n;i++){uint32_t v=uint32_t((i*17)%256)|(uint32_t((i*31+3)%256)<<8)|(uint32_t((i*47+7)%256)<<16)|(uint32_t((i*61+11)%256)<<24);memcpy(&host[i],&v,4);}T*a,*d;cudaMalloc(&a,n*4);cudaMalloc(&d,(n/4096)*4);cudaMemcpy(a,host.data(),n*4,cudaMemcpyHostToDevice);for(int mode=0;mode<2;mode++){cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<(warmup?1:repeat);j++){if(mode==0)dot_product<T,1><<<n/4096,1024>>>(a,a,d,n/4);else dot_product2<T,1><<<n/4096,1024>>>(a,a,d,n/4);}cudaDeviceSynchronize();times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat);cudaMemcpy(out.data(),d,(n/4096)*4,cudaMemcpyDeviceToHost);for(auto v:out)values.push_back(double(v));for(int block=0;block<n/4096;block++){double sum=0;for(int i=block*4096;i<(block+1)*4096;i++){uint32_t v;memcpy(&v,&host[i],4);for(int shift=0;shift<32;shift+=8){int byte=(v>>shift)&255;if(std::is_same_v<T,int>&&byte>=128)byte-=256;sum+=byte*byte;}}expected.push_back(sum);}}cudaFree(a);cudaFree(d);}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):16384,repeat=argc>2?atoi(argv[2]):10;std::vector<double>times,values,expected;study_type<int>(n,repeat,times,values,expected,true);study_type<unsigned>(n,repeat,times,values,expected,true);for(int trial=1;trial<=5;trial++){times.clear();values.clear();expected.clear();study_type<int>(n,repeat,times,values,expected,false);study_type<unsigned>(n,repeat,times,values,expected,false);double total=0;for(double t:times)total+=t;emit(trial,total,values,expected,repeat);}return 0;}
